/* Secure, sandbox-only Stripe Connect panels. Demo workspace roles confer no API access. */
let hfConnectInstance=null,hfConnectAccount=null,hfConnectScript=null;
const connectExtraBefore=renderExtraView;
renderExtraView=function(v){if(['hConnect','pConnect'].includes(v)){if(!isStaff())return head('Staff access required.','');return `${head(state.role==='Owner HQ'?'Shop payments.':'Your payouts.','Your account, balances and payout settings.')}<section class="panel connect-panel"><div class="row between"><h2>Payments & payouts</h2><span class="badge">Sandbox</span></div><p class="muted connect-intro">Test onboarding, bank details and payouts without moving real money.</p><div id="connect-content" role="status"><span class="ticket-spinner" aria-hidden="true"></span> Checking your sandbox account…</div></section>`;}return connectExtraBefore(v);};
async function hfConnectRequest(path,body){const r=await fetch('/api/connect/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok){const err=new Error(data.error||'Unable to connect. Please try again.');err.status=r.status;throw err;}return data;}
function hfConnectLoad(){if(window.StripeConnect?.init)return Promise.resolve();if(hfConnectScript)return hfConnectScript;hfConnectScript=new Promise((resolve,reject)=>{const script=document.createElement('script');let timer;const failed=()=>{clearTimeout(timer);script.remove();hfConnectScript=null;reject(Error('Stripe could not load. Check your connection and retry.'));};const ready=()=>{if(!window.StripeConnect?.init)return;clearTimeout(timer);resolve();};window.StripeConnect=window.StripeConnect||{};window.StripeConnect.onLoad=ready;script.src='https://connect-js.stripe.com/v1.0/connect.js';script.async=true;script.onload=ready;script.onerror=failed;timer=setTimeout(failed,25000);document.head.append(script);});return hfConnectScript;}
function hfConnectLoginHTML(){return `<h3>Sign in to your payout account</h3><p class="muted">Use your sandbox staff credentials. Changing the workspace does not change access to money.</p><form id="connect-login"><label class="field">Username<input name="username" autocomplete="username" required maxlength="80"></label><label class="field">Password<input type="password" name="password" autocomplete="current-password" required maxlength="256"></label><p class="connect-error" role="alert"></p><button class="btn">Sign in securely</button></form>`;}
async function hfConnectBoot(){const host=document.querySelector('#connect-content');if(!host)return;try{const config=await hfConnectRequest('config');if(!host.isConnected)return;if(!config.ready){host.innerHTML='<div class="notice"><strong>Sandbox setup is not connected yet.</strong><p>Add the platform’s sandbox credentials and staff access in Vercel to begin. No real money can move from this panel.</p><button class="btn secondary" data-connect="retry">Check setup again</button></div>';return;}let user;try{user=await hfConnectRequest('me');}catch(e){if(e.status!==401)throw e;if(host.isConnected)host.innerHTML=hfConnectLoginHTML();return;}if(!host.isConnected)return;
 const expected=state.role==='Owner HQ'?'owner':'barber';if(user.role!==expected){host.innerHTML=`<p>Signed in as ${esc(user.displayName)} (${esc(user.role)}).</p><p class="muted">Sign out to access the payout account for this workspace.</p><button class="btn secondary" data-connect="logout">Sign out</button>`;return;}
 if(!user.accountId){host.innerHTML=`<h3>${esc(user.displayName)}</h3><p class="muted">Connect your own business to accept payments and manage your payouts.</p><div class="notice">Independent barbers can connect their own merchant account. Commission or wage payments from a shop are separate and will not appear here.</div><button class="btn" data-connect="create">Set up sandbox account</button><button class="text-btn" data-connect="logout">Sign out</button><p class="connect-error" role="alert"></p>`;return;}
 host.innerHTML=`<div class="connect-signed-in"><div><strong>${esc(user.displayName)}</strong><small>${esc(user.role==='owner'?'Shop merchant account':'Independent barber account')}</small></div><button class="text-btn" data-connect="logout">Sign out</button></div><div class="connect-tabs" role="group" aria-label="Payment tools">${[['payouts','Payouts'],['account-onboarding','Onboarding'],['account-management','Settings'],['payments','Payments']].map(([id,label])=>`<button class="btn secondary small ${id==='payouts'?'selected':''}" data-connect="tab" data-component="${id}">${label}</button>`).join('')}</div><div id="connect-status" class="connect-balance-grid" aria-live="polite">Loading account status…</div><div class="notice connect-payout-note">Instant payouts appear when Stripe confirms eligibility, an eligible payout destination and available funds. Stripe shows the fee before confirmation. Sandbox payouts do not move real money.</div><div id="connect-notifications"></div><p id="connect-component-error" class="connect-error" role="alert"></p><div id="connect-component"><span class="ticket-spinner" aria-hidden="true"></span> Loading Stripe…</div><small class="muted">Shop-to-barber commissions and payroll are separate from independent merchant payouts.</small>`;
 await hfConnectLoad();if(!host.isConnected)return;if(hfConnectAccount!==user.accountId||!hfConnectInstance){await hfConnectInstance?.logout();hfConnectInstance=window.StripeConnect.init({publishableKey:config.publishableKey,fetchClientSecret:async()=>{const data=await hfConnectRequest('session',{});return data.clientSecret;},appearance:{overlays:'dialog',variables:{colorPrimary:'#bd2332',colorBackground:'#1c1d20',colorText:'#f3f1ec',colorSecondaryText:'#a4a5ae',borderRadius:'12px',fontFamily:'Arial, sans-serif'}}});hfConnectAccount=user.accountId;}
 const banner=hfConnectInstance.create('notification-banner');banner.setOnLoadError?.(()=>hfConnectComponentError('Stripe needs attention. Open Onboarding to review your account.'));host.querySelector('#connect-notifications').append(banner);hfConnectMount('payouts');await hfConnectRefresh();
 }catch(e){if(host.isConnected)host.innerHTML=`<p class="connect-error" role="alert">${esc(e.message)}</p><button class="btn secondary" data-connect="retry">Try again</button>`;}}
function hfConnectComponentError(message){const el=document.querySelector('#connect-component-error');if(el)el.textContent=message;}
function hfConnectMount(name){const host=document.querySelector('#connect-component');if(!host||!hfConnectInstance)return;hfConnectComponentError('');const element=hfConnectInstance.create(name);element.setOnLoadError?.(()=>hfConnectComponentError('Stripe could not display this tool. Check onboarding and try again.'));if(name==='account-onboarding')element.setOnExit?.(()=>{hfConnectMount('payouts');hfConnectRefresh();});host.replaceChildren(element);document.querySelectorAll('[data-component]').forEach(b=>b.classList.toggle('selected',b.dataset.component===name));}
async function hfConnectRefresh(){const host=document.querySelector('#connect-status');if(!host)return;try{const s=await hfConnectRequest('status');if(!host.isConnected)return;const usd=items=>cents(items.filter(x=>x.currency==='usd').reduce((n,x)=>n+x.amount,0));host.innerHTML=`<div><small>Available balance</small><strong>${usd(s.available)}</strong></div><div><small>Pending balance</small><strong>${usd(s.pending)}</strong></div><div><small>Instant-eligible balance</small><strong>${usd(s.instantAvailable)}</strong></div><p>${s.chargesEnabled?'Payments enabled':'Finish onboarding to accept payments'} · ${s.payoutsEnabled?'Payouts enabled':'Payouts not yet enabled'}<br><small>Updates automatically · sandbox balances in USD</small></p>`;}catch(e){if(host.isConnected)host.textContent=e.message;}}
const renderBeforeConnect=render;render=function(){renderBeforeConnect();if(!isStaff())return;const page=state.role==='Owner HQ'?'hConnect':'pConnect';if(['more','hPayouts','pPayout','earnings'].includes(state.view)){const main=document.querySelector('main');main?.insertAdjacentHTML('afterbegin',`<button class="barber-availability connect-shortcut" data-view="${page}">${icon('wallet')}<span><strong>Payments & payouts</strong><small>Connect your account · payout settings · instant payouts</small></span>${icon('chevron')}</button>`);}if(['hConnect','pConnect'].includes(state.view))queueMicrotask(hfConnectBoot);};
document.addEventListener('submit',async e=>{if(e.target.id!=='connect-login')return;e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const fields=new FormData(form);await hfConnectRequest('login',{username:fields.get('username'),password:fields.get('password')});form.reset();await hfConnectBoot();}catch(err){if(form.isConnected)form.querySelector('.connect-error').textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-connect]');if(!button)return;const action=button.dataset.connect;button.disabled=true;try{if(action==='retry')await hfConnectBoot();if(action==='create'){await hfConnectRequest('account',{});await hfConnectBoot();hfConnectMount('account-onboarding');}if(action==='tab')hfConnectMount(button.dataset.component);if(action==='logout'){await hfConnectInstance?.logout();hfConnectInstance=null;hfConnectAccount=null;await hfConnectRequest('logout',{});await hfConnectBoot();}}catch(err){const target=document.querySelector('.connect-error');if(target)target.textContent=err.message;else toast(err.message);}finally{button.disabled=false;}});
setInterval(()=>{if(!document.hidden&&['hConnect','pConnect'].includes(state.view))hfConnectRefresh();},20000);
render();
